def can_add_event(current_events, new_event):
    from datetime import datetime, timedelta

    def event_end_time(event):
        start_time = datetime.strptime(event["date"], "%Y-%m-%d") + datetime.strptime(event["start_time"], "%H:%M")
        return start_time + timedelta(hours=2)

    for event in current_events:
        event_end_time_obj = event_end_time(event)
        new_event_start_time_obj = datetime.strptime(new_event["date"], "%Y-%m-%d") + datetime.strptime(new_event["start_time"], "%H:%M")

        if new_event_start_time_obj < event_end_time_obj:
            return False

    return True

def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12:
        return None

    total_savings = 0
    for i in range(12):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)) or income[i] < 0 or expenses[i] < 0:
            return None
        monthly_savings = income[i] - expenses[i]
        total_savings += monthly_savings

    if total_savings < 0:
        return None

    average_savings = total_savings / 12
    return average_savings

